INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $c13q${"question":"Hvad var Winston Churchills historiske betydning som Storbritanniens leder i 2. Verdenskrig?","options":["Churchill holdt fast i britisk modstand i 1940 da presset for at søge forhandlingsfred med Hitler var størst — hans lederevner og retorik cementerede den politiske og folkelige vilje til at kæmpe og forhindrede et britisk forligsfredssøgning","Churchill koordinerede den britiske atombombeudvikling som var afgørende for krigens afslutning","Churchill var ubetydelig for krigens resultat — USA vandt krigen med britisk neutral opbakning","Churchill beordrede personligt D-dag og var ansvarlig for den militære planlægning af Normandiet-landgangen"],"correct":"Churchill holdt fast i britisk modstand i 1940 da presset for at søge forhandlingsfred med Hitler var størst — hans lederevner og retorik cementerede den politiske og folkelige vilje til at kæmpe og forhindrede et britisk forligsfredssøgning","accepted_answers":["Churchill holdt fast i britisk modstand i 1940 da presset for at søge forhandlingsfred med Hitler var størst — hans lederevner og retorik cementerede den politiske og folkelige vilje til at kæmpe og forhindrede et britisk forligsfredssøgning"],"review_text":"Da Frankrig faldt i juni 1940 var Churchill britisk premierminister siden to måneder. Indflydelsesrige stemmer i det britiske kabinet — herunder udenrigsminister Lord Halifax — pressede på for forhandlingsfred med Hitler. Churchill afviste kategorisk. I tre berømte taler sommeren 1940 sagde han bl.a. at briterne ville kæmpe på strandene og aldrig overgive sig. Om hans valg var rigtigt fra et rent rationelt perspektiv er historisk omdiskuteret — men det forhindrede et forlig der sandsynligvis ville have frigivet tyske ressourcer til at slå Sovjet og befæste Europa. Enkeltpersoners valg kan have historisk afgørende konsekvenser."}$c13q$::jsonb,
  'mc','short',$c13m${"concepts":["Churchill","britisk modstand","forhandlingsfred","retorik","lederskab","1940"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"analytical_challenge","domain":"world_war_2"}$c13m$::jsonb,
  'mc_single',4,'auto',true,'world_war_2',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $c14q${"question":"Hvad viser historisk forskning om de mennesker der udøvede Holocaust — hvem var gerningsmændene?","options":["Forskning som Christopher Brownings om Reservepolitibataljon 101 viser at mange gerningsmænd var ordinaere mennesker uden fanatisk ideologi — konformitetspres og lydighed over for autoritet var vigtigere motivationer end medfodt ondskab","Forskning viser entydigt at alle Holocaust-gerningsmaend var ideologisk overbevist om nazismens retfaerdighed","Forskning viser at Holocaust kun var mulig fordi alle gerningsmaend var psykisk syge og ikke normale mennesker","Historikere er enige om at kun en lille SS-elite var ansvarlig — den brede befolkning vidste intet og bidrog slet ikke"],"correct":"Forskning som Christopher Brownings om Reservepolitibataljon 101 viser at mange gerningsmænd var ordinaere mennesker uden fanatisk ideologi — konformitetspres og lydighed over for autoritet var vigtigere motivationer end medfodt ondskab","accepted_answers":["Forskning som Christopher Brownings om Reservepolitibataljon 101 viser at mange gerningsmænd var ordinaere mennesker uden fanatisk ideologi — konformitetspres og lydighed over for autoritet var vigtigere motivationer end medfodt ondskab"],"review_text":"I sin bog Ordinary Men (1992) analyserede Christopher Browning Reservepolitibataljon 101 — middelaldrende tyske mænd der ikke var SS-fanatikere. De fik valget om at deltage i masseudskydninger eller melde sig fra. Meget få meldte fra. Browning argumenterer at frygten for at skille sig ud, gruppepres og gradvis dehumanisering af ofrene var mere forklarende end ideologisk had. Hannah Arendt formulerede lignende pointer med begrebet det ondes banalitet i sin analyse af Adolf Eichmann. Det er en ubehagelig lektie: moralske katastrofer kræver ikke monstre — de kræver systemer der normaliserer ondskab."}$c14q$::jsonb,
  'mc','short',$c14m${"concepts":["ordinaere gerningsmaend","Browning","Arendt","det ondes banalitet","konformitet","lydighed"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"analytical_challenge","domain":"world_war_2"}$c14m$::jsonb,
  'mc_single',4,'auto',true,'world_war_2',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $c15q${"question":"Hvad var den direkte årsag til at Tyskland blev delt i Vest- og Østtyskland efter 2. Verdenskrig?","options":["De fire sejrende magter delte Tyskland i besættelseszoner — den voksende spænding mellem vest og øst betød at de vestlige zoner fusionerede til Vesttyskland (BRD) og den sovjetiske zone blev til Østtyskland (DDR) i 1949","Det var en frivillig tysk beslutning at dele landet for at undgå fremtidige krige","FN besluttede at dele Tyskland som kollektiv straf for Holocaust og krigen","USA og Sovjet delte Tyskland fysisk i 1945 med en permanent mur fra dag ét"],"correct":"De fire sejrende magter delte Tyskland i besættelseszoner — den voksende spænding mellem vest og øst betød at de vestlige zoner fusionerede til Vesttyskland (BRD) og den sovjetiske zone blev til Østtyskland (DDR) i 1949","accepted_answers":["De fire sejrende magter delte Tyskland i besættelseszoner — den voksende spænding mellem vest og øst betød at de vestlige zoner fusionerede til Vesttyskland (BRD) og den sovjetiske zone blev til Østtyskland (DDR) i 1949"],"review_text":"Efter Tysklands kapitulation i maj 1945 delte USA, Storbritannien, Frankrig og Sovjet landet i fire besættelseszoner. Berlin blev ligeledes delt. Oprindeligt var hensigten midlertidig — men den voksende ideologiske og politiske kløft mellem Vest og Øst (Den Kolde Krig) betød at de vestlige zoner fusionerede til Forbundsrepublikken Tyskland (BRD) i maj 1949, og den sovjetiske zone blev til Den Tyske Demokratiske Republik (DDR) i oktober 1949. Tyskland forblev delt i 40 år til Berlinmurens fald i 1989 og den formelle genforening i 1990."}$c15q$::jsonb,
  'mc','short',$c15m${"concepts":["Tysklands deling","besættelseszoner","BRD","DDR","1949","Den Kolde Krig"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"causal","insight_type":"concept_clarification","challenge_role":"analytical_challenge","domain":"world_war_2"}$c15m$::jsonb,
  'mc_single',4,'auto',true,'world_war_2',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $c16q${"question":"Hvad viser den internationale reaktion på nazisternes jødeforfølgelse i 1930'erne om tilskueres ansvar?","options":["Mange lande vidste om forfølgelserne men lukkede grænserne for jødiske flygtninge og reagerede ikke militært — det viser at passivitet ikke er neutral men kan muliggøre forfølgelse","Alle vestlige lande åbnede straks deres grænser for jødiske flygtninge da forfølgelserne begyndte","Ingen lande vidste noget om forfølgelserne af jøder før befrielsen af lejrene i 1945","FN fordømte nazisternes forfølgelse af jøder officielt i 1937 og krævede at det stoppede"],"correct":"Mange lande vidste om forfølgelserne men lukkede grænserne for jødiske flygtninge og reagerede ikke militært — det viser at passivitet ikke er neutral men kan muliggøre forfølgelse","accepted_answers":["Mange lande vidste om forfølgelserne men lukkede grænserne for jødiske flygtninge og reagerede ikke militært — det viser at passivitet ikke er neutral men kan muliggøre forfølgelse"],"review_text":"I 1938 mødtes 32 nationer i Évian i Frankrig for at diskutere den jødiske flygtningekrise. Næsten alle lukkede dørene — inklusive USA og Storbritannien der var bange for at importere fattigdom og antisemitisk modstand hjemme. Det tyske regime noterede tilfreds at Vesten talte om humanitære hensyn men i praksis nægtede at tage imod jøderne. Denne internationale passivitet i 1930'erne er ikke den direkte årsag til Holocaust — men den fjernede en mulig flugtvej. At tilskuere — individer, institutioner og nationer — har et ansvar for at reagere på forfølgelse er en central etisk lektie fra 2. Verdenskrig."}$c16q$::jsonb,
  'mc','short',$c16m${"concepts":["tilskueres ansvar","flygtninge","Évian","passivitet","international reaktion","bystanders"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"analytical_challenge","domain":"world_war_2"}$c16m$::jsonb,
  'mc_single',4,'auto',true,'world_war_2',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $c17q${"question":"Hvad kendetegnede behandlingen af civile i 2. Verdenskrig sammenlignet med 1. Verdenskrig?","options":["2. Verdenskrig var i langt højere grad en krig mod civile — strategiske bombninger af byer, udryddelseslejre og systematisk folkemord betød at et flertal af de ca. 70-85 millioner ofre var civile ikke soldater","2. Verdenskrig havde proportionelt færre civile ofre end 1. Verdenskrig fordi bombardementsteknikken var mere præcis","2. Verdenskrig var en rent militær konflikt — civile befolkninger var beskyttet og ikke involveret i kamphandlingerne","Behandlingen af civile var identisk i 1. og 2. Verdenskrig da begge krige fulgte de samme folkeretslige regler"],"correct":"2. Verdenskrig var i langt højere grad en krig mod civile — strategiske bombninger af byer, udryddelseslejre og systematisk folkemord betød at et flertal af de ca. 70-85 millioner ofre var civile ikke soldater","accepted_answers":["2. Verdenskrig var i langt højere grad en krig mod civile — strategiske bombninger af byer, udryddelseslejre og systematisk folkemord betød at et flertal af de ca. 70-85 millioner ofre var civile ikke soldater"],"review_text":"1. Verdenskrig var primært en krig mellem soldater i skyttegrave — civile ofre var massive men overvejende indirekte (sult, sygdom). 2. Verdenskrig brød med dette: bomber over London, Dresden, Tokyo og Hiroshima dræbte bevidst civile. Holocaust udryddede seks millioner civile jøder systematisk. Japanske massedrab i Kina (Nanjing-massakren). Tyske destruktioner af byer i Sovjet og Polen. Af de anslået 70-85 millioner krigsofre var 40-55% civile. Det ændrede fundamentalt den internationale folkeretslige forståelse af hvad krig er og hvem der er legitimt mål."}$c17q$::jsonb,
  'mc','short',$c17m${"concepts":["civile ofre","total krig","bombninger","Holocaust","folkemord","folkeretten"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"analytical_challenge","domain":"world_war_2"}$c17m$::jsonb,
  'mc_single',4,'auto',true,'world_war_2',7,4
);

-- ─── BAND 5 (3 questions) ─────────────────────────────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $c18q${"question":"Var USA's brug af atombomber mod Hiroshima og Nagasaki moralsk forsvarlig — og hvad siger den historiske debat?","options":["En vedvarende etisk og historisk debat: forsvarerne argumenterer at bomberne forkortede krigen og reddede millioner af liv ved at undgå en blodig landinvasion — kritikerne svarer at Japan allerede var tæt på overgivelse og at massedrabet på civile aldrig kan retfærdiggøres","Der er historisk og etisk konsensus om at atombomberne var fuldstændig moralsk forsvarlige og retfærdige","Der er historisk og etisk konsensus om at atombomberne var en krigsforbrydelse og USA er officielt blevet domfældt for det","Debatten er rent teknisk og handler kun om militær effektivitet — etik er irrelevant i krig"],"correct":"En vedvarende etisk og historisk debat: forsvarerne argumenterer at bomberne forkortede krigen og reddede millioner af liv ved at undgå en blodig landinvasion — kritikerne svarer at Japan allerede var tæt på overgivelse og at massedrabet på civile aldrig kan retfærdiggøres","accepted_answers":["En vedvarende etisk og historisk debat: forsvarerne argumenterer at bomberne forkortede krigen og reddede millioner af liv ved at undgå en blodig landinvasion — kritikerne svarer at Japan allerede var tæt på overgivelse og at massedrabet på civile aldrig kan retfærdiggøres"],"review_text":"Debatten om atombomberne er en af moderne histories mest vedvarende etiske diskussioner. Forsvarerne (traditionelle historikere): en landinvasion af Japan kunne have kostet en million amerikanske og millioner af japanske liv — bomberne afkortede krigen og reddede liv netto. Kritikerne (revisionister fra 1960'erne): japanske signaler om overgivelsesvilje var allerede tydelige; bomberne var primært geopolitisk signalering over for Sovjet; og massedrab på civile kan aldrig retfærdiggøres uanset strategisk mål. En tredje position: begge faktorer var reelle — den moralske vurdering afhænger af hvilke konsekvenser man tillægger størst vægt. Debatten er ikke afsluttet."}$c18q$::jsonb,
  'mc','short',$c18m${"concepts":["atombomber","etisk debat","Hiroshima","landinvasion","civile ofre","historikerdebat"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_2"}$c18m$::jsonb,
  'mc_single',5,'auto',true,'world_war_2',7,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $c19q${"question":"Hvad fortæller Milgrams lydighedseksperiment (1961) om de psykologiske mekanismer bag Holocaust?","options":["Eksperimentet viste at ordinaere mennesker er villige til at paafore andre alvorlig skade naar en autoritetsfigur beordrer dem til det — det understøtter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke kraevede monstre men systemer der normaliserede lydighed","Eksperimentet beviste at alle mennesker er naturligt onde og bevidst oensker at skade andre","Eksperimentet er videnskabeligt ugyldigt og bruges aldrig i serioes historisk forskning om Holocaust","Eksperimentet viser at Holocaust kun var mulig fordi tyskerne genetisk er mere lydige end andre folk"],"correct":"Eksperimentet viste at ordinaere mennesker er villige til at paafore andre alvorlig skade naar en autoritetsfigur beordrer dem til det — det understøtter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke kraevede monstre men systemer der normaliserede lydighed","accepted_answers":["Eksperimentet viste at ordinaere mennesker er villige til at paafore andre alvorlig skade naar en autoritetsfigur beordrer dem til det — det understøtter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke kraevede monstre men systemer der normaliserede lydighed"],"review_text":"Stanley Milgram udforte sit beroemte lydigheds-eksperiment i 1961 i kolvandet paa Eichmann-retssagen. Forsøgspersoner (ordinaere amerikanere) blev bedt om at give elektrisk stoede til en skuespiller i et andet rum naar en forsøgsleder sagde at de skulle forsaette. 65 procent gave de stoerkeste stoede paa troeds af hoere raab om smerter. Milgram fortolkede resultatet som lydighed over for autoritet under et system der frigjorde individet fra ansvar. Hannah Arendt havde to aar forinden moentet begrebet det ondes banalitet om Adolf Eichmann — en bureaukrat der organiserede Holocaust ikke af had men af pedantisk embedslydig. Begge perspektiver understreger at moralsk ondskab ikke kraever moralske monstre."}$c19q$::jsonb,
  'mc','short',$c19m${"concepts":["Milgram","lydighed","autoritet","Arendt","det ondes banalitet","psykologi og Holocaust"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_2"}$c19m$::jsonb,
  'mc_single',5,'auto',true,'world_war_2',7,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $c20q${"question":"Hvad er den vigtigste historiske lektie fra 2. Verdenskrig for forståelsen af demokratiets skrøbelighed?","options":["At demokratier kan demokratisk vaelge en leder der afvikler demokratiet — Hitlers magtovertagelse var ikke et coup men et produkt af valgsystemets sammenbrud under ekstrem okonomisk krise og social stress der forpligter nutidige demokratier til aktiv forfatningsbeskyttelse","Demokratier er naturligt selvopretholdte og kan aldrig kollapse indefra — 2. Verdenskrig er et unikt historisk undtagelsestilfaelde","Lektien fra 2. Verdenskrig er udelukkende militaer: demokratier skal have staerke haere for at forhindre invasion","Demokratiet var ikke under pres i 2. Verdenskrig — Hitler kom til magten via militaerkup ikke demokratiske valg"],"correct":"At demokratier kan demokratisk vaelge en leder der afvikler demokratiet — Hitlers magtovertagelse var ikke et coup men et produkt af valgsystemets sammenbrud under ekstrem okonomisk krise og social stress der forpligter nutidige demokratier til aktiv forfatningsbeskyttelse","accepted_answers":["At demokratier kan demokratisk vaelge en leder der afvikler demokratiet — Hitlers magtovertagelse var ikke et coup men et produkt af valgsystemets sammenbrud under ekstrem okonomisk krise og social stress der forpligter nutidige demokratier til aktiv forfatningsbeskyttelse"],"review_text":"Weimarrepublikkens kollaps er demokratihistoriens mest studerede fallit. Den tyske forfatning af 1919 var progressiv — men den indeholdt noedudstykkene der tillod suspensionen af borgernes rettigheder under undtagelsestilstand (§ 48). Hyperinflation i 1923, verdenskrisen fra 1929 og politisk fragmentering skabte kaos og fortvivlelse som Hitler og NSDAP udnyttede. I januar 1933 blev Hitler udnaevnt til kansler af den aeldgamle Hindenburg — ad legal vej, ikke ved statskup. Den tyske demokratiske institution valgte sin egen baeddelmand. Det er den dybeste lektie: demokrati er ikke en selvfoelge men kraever aktiv vedligeholdelse, forfatningsbeskyttelse og borgere der forsvarer dets principper ogsaa under krisetider."}$c20q$::jsonb,
  'mc','short',$c20m${"concepts":["demokratiets skrøbelighed","Weimarrepublikken","Hitler","forfatningsbeskyttelse","valgsystemets sammenbrud","borgerpligt"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_2"}$c20m$::jsonb,
  'mc_single',5,'auto',true,'world_war_2',7,5
);
